public class StateWatcher extends Thread {
    private String seenInside = "not run yet";

    public StateWatcher(String name) {
        super(name);                       // the thread's name
    }

    @Override
    public void run() {
        seenInside = getState().toString();   // what the thread sees while it runs
        try {
            Thread.sleep(200);             // pause 0.2 second: TIMED_WAITING
        } catch (InterruptedException e) {
            seenInside = "interrupted";
        }
    }

    public String getSeenInside() { return seenInside; }
}

public class Main {
    public static void main(String[] args) {
        StateWatcher w = new StateWatcher("TRC 456");
        System.out.println("Before start(): " + w.getState() + ", alive? " + w.isAlive());

        w.start();                         // NEW -> RUNNABLE
        try {
            w.join();                      // main waits until run() ends
        } catch (InterruptedException e) {
            System.out.println("main was interrupted");
        }
        System.out.println("Inside run(): " + w.getSeenInside());
        System.out.println("After join(): " + w.getState() + ", alive? " + w.isAlive());

        try {
            w.start();                     // a thread can run only ONCE
        } catch (IllegalThreadStateException e) {
            System.out.println("Start it again? Not allowed: a thread runs only once.");
        }
    }
}

