public class ReadyReport implements Runnable {
    private String plate;
    private int delayMs;                   // ms to get ready
    private CountDownLatch latch;
    private String status = "not ready";

    public ReadyReport(String plate, int delayMs, CountDownLatch latch) {
        this.plate = plate;
        this.delayMs = delayMs;
        this.latch = latch;
    }

    @Override
    public void run() {
        try {
            Thread.sleep(delayMs);
            status = "ready";
        } catch (InterruptedException e) {
            status = "interrupted";
        } finally {
            latch.countDown();             // count goes down by 1, no matter what
        }
    }

    public String getPlate() { return plate; }
    public String getStatus() { return status; }
}

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;

public class Main {
    public static void main(String[] args) {
        CountDownLatch latch = new CountDownLatch(4);      // wait for 4 reports
        List<ReadyReport> reports = new ArrayList<>();
        reports.add(new ReadyReport("NXA 123", 400, latch));
        reports.add(new ReadyReport("TRC 456", 100, latch));
        reports.add(new ReadyReport("BUS 789", 300, latch));
        reports.add(new ReadyReport("NYB 321", 200, latch));

        System.out.println("Dispatcher waits. Reports still needed: " + latch.getCount());
        for (ReadyReport r : reports) {
            new Thread(r).start();
        }
        try {
            latch.await();                 // main stops here until the count is 0
        } catch (InterruptedException e) {
            System.out.println("Dispatcher was interrupted");
        }
        for (ReadyReport r : reports) {    // results in a FIXED order, after await
            System.out.println(r.getPlate() + " reports: " + r.getStatus());
        }
        System.out.println("Reports still needed: " + latch.getCount());
        System.out.println("All vehicles ready. Dispatch begins!");
    }
}

