import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CyclicBarrier;

public class ConvoyLeg implements Runnable {
    private String plate;
    private int delayMs;
    private CyclicBarrier barrier;
    private String lastStop = "not left yet";

    public ConvoyLeg(String plate, int delayMs, CyclicBarrier barrier) {
        this.plate = plate;
        this.delayMs = delayMs;
        this.barrier = barrier;
    }

    // drive to a stop, then wait there until the whole convoy has arrived
    private void driveTo(String stop) throws InterruptedException, BrokenBarrierException {
        Thread.sleep(delayMs);
        int stillComing = barrier.await(); // wait for the others
        if (stillComing == 0) {            // 0 = the LAST one to arrive
            System.out.println("-- All here at " + stop + ". The convoy moves on together!");
        }
        lastStop = stop;
    }

    @Override
    public void run() {
        try {
            driveTo("Monumento");
            driveTo("Recto");              // the SAME barrier is used again
        } catch (InterruptedException | BrokenBarrierException e) {
            lastStop = "left the convoy";
        }
    }

    public String getPlate() { return plate; }
    public String getLastStop() { return lastStop; }
}

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CyclicBarrier;

public class Main {
    public static void main(String[] args) {
        CyclicBarrier barrier = new CyclicBarrier(3);  // 3 in the convoy
        List<ConvoyLeg> legs = new ArrayList<>();
        legs.add(new ConvoyLeg("NXA 123", 300, barrier));
        legs.add(new ConvoyLeg("NYB 321", 100, barrier));
        legs.add(new ConvoyLeg("BUS 789", 200, barrier));

        List<Thread> convoy = new ArrayList<>();
        for (ConvoyLeg leg : legs) {
            convoy.add(new Thread(leg));
        }
        for (Thread t : convoy) {
            t.start();
        }
        try {
            for (Thread t : convoy) {
                t.join();
            }
        } catch (InterruptedException e) {
            System.out.println("main was interrupted");
        }
        for (ConvoyLeg leg : legs) {       // results in a FIXED order, after join
            System.out.println(leg.getPlate() + " reached " + leg.getLastStop());
        }
        System.out.println("Convoy finished.");
    }
}

