import java.util.concurrent.Semaphore;

public class LoadingBay implements Runnable {
    private String plate;
    private int arriveMs;                  // when this vehicle reaches the terminal
    private Semaphore bays;
    private String result = "not run yet";

    public LoadingBay(String plate, int arriveMs, Semaphore bays) {
        this.plate = plate;
        this.arriveMs = arriveMs;
        this.bays = bays;
    }

    @Override
    public void run() {
        try {
            Thread.sleep(arriveMs);
            bays.acquire();                // take a bay, or WAIT until one is free
            try {
                Thread.sleep(400);         // loading takes time
                result = "loaded, then left the bay";
            } finally {
                bays.release();            // give the bay back, always
            }
        } catch (InterruptedException e) {
            result = "interrupted";
        }
    }

    public String getPlate() { return plate; }
    public String getResult() { return result; }
}

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Semaphore;

public class Main {
    public static void main(String[] args) {
        Semaphore bays = new Semaphore(2);                 // 2 bays only
        System.out.println("Free bays at the start: " + bays.availablePermits());
        List<LoadingBay> jobs = new ArrayList<>();
        jobs.add(new LoadingBay("NXA 123", 0, bays));
        jobs.add(new LoadingBay("TRC 456", 100, bays));
        jobs.add(new LoadingBay("BUS 789", 200, bays));
        jobs.add(new LoadingBay("NYB 321", 300, bays));

        List<Thread> line = new ArrayList<>();
        for (LoadingBay job : jobs) {
            line.add(new Thread(job));
        }
        for (Thread t : line) {
            t.start();
        }
        for (Thread t : line) {
            try {
