        Semaphore bays = new Semaphore(1);        // 1 boarding bay only
        Vehicle[] fleet = {
            new Jeepney("NXA 123", "Mang Ramon", "Monumento-Divisoria"),
            new Tricycle("TRC 456", "Kuya Ben", "Bagong Silang TODA"),
            new Bus("BUS 789", "Aling Rosa", 50),
            new Jeepney("NYB 321", "Mang Tonyo", "Sangandaan-Recto")
        };
        int[] riders = {12, 6, 30, 15};
        List<BayBoarding> jobs = new ArrayList<>();
        List<Thread> line = new ArrayList<>();
        for (int i = 0; i < fleet.length; i++) {
            jobs.add(new BayBoarding(fleet[i], riders[i], bays));
            line.add(new Thread(jobs.get(i), fleet[i].getPlateNumber()));
        }
        for (Thread t : line) {
            t.start();
        }
        try {
            for (Thread t : line) {
                t.join();
            }
        } catch (InterruptedException e) {
            System.out.println("main was interrupted");
        }
        for (int i = 0; i < line.size(); i++) {   // fixed order
            System.out.println(line.get(i).getName() + ": " + jobs.get(i).getResult());
        }
        System.out.println("Free bays: " + bays.availablePermits());
    }
}

