    }
}

public class VehicleNotFoundException extends Exception {
    public VehicleNotFoundException(String message) {
        super(message);
    }
}

public class DispatchThread extends Thread {      // a Thread that does dispatch work
    private Vehicle vehicle;
    private int trips;
    private double collected = 0;
    private String ranOn = "not run yet";

    public DispatchThread(Vehicle vehicle, int trips) {
        super(vehicle.getPlateNumber());   // the thread's name is the plate
        this.vehicle = vehicle;
        this.trips = trips;
    }

    @Override
    public void run() {                    // the job this thread does
        ranOn = Thread.currentThread().getName();
        for (int i = 1; i <= trips; i++) {
            collected = collected + vehicle.quoteFare(5);
            try {
                Thread.sleep(100);         // one trip takes time (0.1 second)
            } catch (InterruptedException e) {
                return;                    // stop early if interrupted
            }
        }
    }

    public double getCollected() { return collected; }
    public String getRanOn() { return ranOn; }
}

public class BoardingTask implements Runnable {   // a JOB, not a thread
    private Vehicle vehicle;
    private int[] groups;                  // passengers arriving, group by group
    private String result = "not run yet";

    public BoardingTask(Vehicle vehicle, int[] groups) {
        this.vehicle = vehicle;
        this.groups = groups;
    }

    @Override
    public void run() {
        try {
            for (int g : groups) {
                vehicle.board(g);          // Week 13: may throw OverloadException
                Thread.sleep(50);
            }
            result = "all boarded";
        } catch (OverloadException e) {
            result = "stopped: " + e.getMessage();
        } catch (InterruptedException e) {
            result = "interrupted";
        }
    }

    public String getResult() { return result; }
}

import java.util.concurrent.CountDownLatch;

public class ReadyReport implements Runnable {
    private String plate;
    private int delayMs;                   // ms to get ready
    private CountDownLatch latch;
    private String status = "not ready";

    public ReadyReport(String plate, int delayMs, CountDownLatch latch) {
        this.plate = plate;
        this.delayMs = delayMs;
        this.latch = latch;
    }

    @Override
    public void run() {
        try {
            Thread.sleep(delayMs);
            status = "ready";
        } catch (InterruptedException e) {
            status = "interrupted";
        } finally {
            latch.countDown();             // count goes down by 1, no matter what
        }
    }

    public String getPlate() { return plate; }
    public String getStatus() { return status; }
}

import java.util.concurrent.BrokenBarrierException;
import java.util.concurrent.CyclicBarrier;

public class ConvoyLeg implements Runnable {
    private String plate;
    private int delayMs;
    private CyclicBarrier barrier;
    private String lastStop = "not left yet";

    public ConvoyLeg(String plate, int delayMs, CyclicBarrier barrier) {
        this.plate = plate;
        this.delayMs = delayMs;
        this.barrier = barrier;
    }

    // drive to a stop, then wait there until the whole convoy has arrived
    private void driveTo(String stop) throws InterruptedException, BrokenBarrierException {
        Thread.sleep(delayMs);
        int stillComing = barrier.await(); // wait for the others
        if (stillComing == 0) {            // 0 = the LAST one to arrive
            System.out.println("-- All here at " + stop + ". The convoy moves on together!");
        }
        lastStop = stop;
    }

    @Override
    public void run() {
        try {
            driveTo("Monumento");
            driveTo("Recto");              // the SAME barrier is used again
        } catch (InterruptedException | BrokenBarrierException e) {
            lastStop = "left the convoy";
        }
    }

    public String getPlate() { return plate; }
    public String getLastStop() { return lastStop; }
}

public class StateWatcher extends Thread {
    private String seenInside = "not run yet";

    public StateWatcher(String name) {
        super(name);                       // the thread's name
    }

    @Override
    public void run() {
        seenInside = getState().toString();   // what the thread sees while it runs
        try {
            Thread.sleep(200);             // pause 0.2 second: TIMED_WAITING
        } catch (InterruptedException e) {
            seenInside = "interrupted";
        }
    }

    public String getSeenInside() { return seenInside; }
}

